script:
frappe.ui.form.on("YOB Store Settings", {
    refresh(frm) {
        show_logo_preview(frm);
    },
    store_logo(frm) {
        show_logo_preview(frm);
    }
});

function show_logo_preview(frm) {
    const fieldname = "store_logo";
    const img_url = frm.doc.store_logo;

    // remove old preview
    frm.get_field(fieldname).$wrapper.find(".yob-logo-preview").remove();

    if (img_url) {
        const full_url = img_url.startsWith("http") ? img_url : window.location.origin + img_url;

        const html = `
            <div class="yob-logo-preview" style="margin-top:10px">
                <img src="${full_url}" style="max-height:120px; border:1px solid #ddd; padding:6px; border-radius:6px;" />
            </div>
        `;

        frm.get_field(fieldname).$wrapper.append(html);
    }
}

frappe.ui.form.on('Category', {

    refresh(frm) {
        render_image_preview(frm, "thumbnail", 200, 200, "No Thumbnail");
        render_image_preview(frm, "banner", "100%", 220, "No Banner Image");

        attach_name_key_listener(frm);

        if (frm.is_new() && frm.doc.category_name) {
            generate_slug(frm);
        }
    },

    // backup: when value changes normally
    category_name(frm) {
        if (!frm.is_new()) return;
        generate_slug(frm);
    },

    // live validation on slug change
    slug(frm) {
        validate_slug_field(frm, true);
    },

    validate(frm) {
        if (!validate_slug_field(frm, true)) {
            frappe.validated = false;
        }
    }
});


// ---------------- REAL TIME LISTENER ----------------

function attach_name_key_listener(frm) {

    if (!frm.is_new()) return;

    const field = frm.get_field("category_name");
    if (!field || !field.$input) return;

    // prevent multiple bindings
    field.$input.off("keyup.yobslug");

    field.$input.on("keyup.yobslug", function () {
        if (!frm.is_new()) return;
        generate_slug(frm);
    });
}


// ---------------- SLUG ----------------

function generate_slug(frm) {

    if (!frm.doc.category_name) return;

    let slug = frm.doc.category_name
        .toLowerCase()
        .trim()
        .replace(/[^a-z0-9\s-]/g, "")
        .replace(/\s+/g, "-")
        .replace(/-+/g, "-");

    frm.set_value("slug", slug);
}


function validate_slug_field(frm, show_msg = false) {

    if (!frm.doc.slug) {
        if (show_msg) frappe.msgprint("Slug is required.");
        return false;
    }

    const valid = /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(frm.doc.slug);

    if (!valid) {
        if (show_msg) {
            frappe.msgprint(
                "Invalid slug format. Use only lowercase letters, numbers and hyphens. Example: red-color"
            );
        }
        return false;
    }

    return true;
}


// ---------------- IMAGE PREVIEW ----------------

function render_image_preview(frm, fieldname, width, height, empty_text) {

    const img_url = frm.doc[fieldname];

    frm.get_field(fieldname).$wrapper.find(".yob-img-preview").remove();

    if (img_url) {
        const full_url = img_url.startsWith("http")
            ? img_url
            : window.location.origin + img_url;

        const html = `
            <div class="yob-img-preview" style="margin-top:10px">
                <img src="${full_url}"
                     style="width:${typeof width === "number" ? width + "px" : width};
                            height:${typeof height === "number" ? height + "px" : height + "px"};
                            object-fit:contain;border:1px solid #ddd;
                            padding:6px;border-radius:8px;background:#fff;" />
            </div>
        `;
        frm.get_field(fieldname).$wrapper.append(html);

    } else {
        const html = `
            <div class="yob-img-preview" style="
                margin-top:10px;width:${typeof width === "number" ? width + "px" : width};
                height:${typeof height === "number" ? height + "px" : height + "px"};
                background:#f2f2f2;border:2px dashed #ccc;border-radius:8px;
                display:flex;align-items:center;justify-content:center;color:#888;">
                ${empty_text}
            </div>
        `;
        frm.get_field(fieldname).$wrapper.append(html);
    }
}

frappe.ui.form.on('Cart', {

    refresh: function(frm) {
        set_queries(frm);
        
        // ---------------- CREATE PAYMENT REQUEST BUTTON ----------------
        if (!frm.is_new() && frm.doc.status === "Draft" && frm.doc.grand_total > 0) {

            frm.add_custom_button("Create Payment Request", function () {

                frappe.call({
                    method: "yob_storefront.api.checkout.create_payment_request_from_cart",
                    args: {
                        cart: frm.doc.name
                    },
                    freeze: true,
                    freeze_message: "Creating Payment Request...",
                    callback: function(r) {

                        if (!r.message) return;

                        if (r.message.success) {

                            frappe.msgprint("Payment Request Created");

                            frappe.set_route(
                                "Form",
                                "Payment Request",
                                r.message.data.payment_request
                            );

                        } else {

                            frappe.msgprint({
                                title: "Error",
                                message: r.message.message,
                                indicator: "red"
                            });

                        }

                    }
                });

            }, "Create");

        }
    },

    // ---------------- CUSTOMER SELECTED ----------------
    customer: function(frm) {

        // Clear dependent fields
        frm.set_value("user", null);
        frm.set_value("billing_address", null);
        frm.set_value("shipping_address", null);
        frm.set_value("contact_person", null);

        set_queries(frm);

        if (!frm.doc.customer) return;

        // Fetch user linked to customer
        frappe.call({
            method: "yob_storefront.api.address.get_user_for_customer",
            args: {
                customer: frm.doc.customer
            },
            callback: function(r) {
                if (r.message) {
                    frm.set_value("user", r.message);
                }
            }
        });

        // Auto-select contact
        frappe.call({
            method: "yob_storefront.api.address.get_contact_for_customer",
            args: {
                customer: frm.doc.customer
            },
            callback: function(r) {
                if (r.message) {
                    frm.set_value("contact_person", r.message);
                }
            }
        });
    },

    // ---------------- SHIPPABLE TOGGLE ----------------
    is_shippable: function(frm) {
        // Clear shipping if not shippable
        if (!frm.doc.is_shippable) {
            frm.set_value("shipping_address", null);
        }

        set_queries(frm);
    }
});


// ---------------- FILTER QUERIES ----------------

function set_queries(frm) {

    // ---------------- NO CUSTOMER ----------------
    if (!frm.doc.customer) {

        frm.set_query("user", () => ({ filters: { name: "" } }));
        frm.set_query("billing_address", () => ({ filters: { name: "" } }));
        frm.set_query("shipping_address", () => ({ filters: { name: "" } }));
        frm.set_query("contact_person", () => ({ filters: { name: "" } }));

        return;
    }

    // ---------------- BILLING ADDRESS ----------------
    frm.set_query("billing_address", function() {
        return {
            query: "frappe.contacts.doctype.address.address.address_query",
            filters: {
                link_doctype: "Customer",
                link_name: frm.doc.customer
            }
        };
    });

    // ---------------- SHIPPING ADDRESS ----------------
    frm.set_query("shipping_address", function() {

        // If not shippable → empty dropdown
        if (!frm.doc.is_shippable) {
            return { filters: { name: "" } };
        }

        return {
            query: "frappe.contacts.doctype.address.address.address_query",
            filters: {
                link_doctype: "Customer",
                link_name: frm.doc.customer
            }
        };
    });

    // ---------------- CONTACT PERSON ----------------
    frm.set_query("contact_person", function() {
        return {
            query: "frappe.contacts.doctype.contact.contact.contact_query",
            filters: {
                link_doctype: "Customer",
                link_name: frm.doc.customer
            }
        };
    });
}

frappe.ui.form.on('Razorpay Payment Log', {
    refresh: function(frm) {

        // -------- STATUS INDICATOR --------
        if (frm.doc.status) {

            let color = "blue";

            if (frm.doc.status === "captured") {
                color = "green";
            }
            else if (frm.doc.status === "failed") {
                color = "red";
            }
            else if (frm.doc.status === "refunded") {
                color = "orange";
            }
            else if (frm.doc.status === "authorized") {
                color = "purple";
            }

            frm.page.set_indicator(frm.doc.status.toUpperCase(), color);
        }

        // -------- REFRESH BUTTON --------
        const final_status = ["captured", "failed", "refunded"];

        if (frm.doc.payment_id && !final_status.includes(frm.doc.status)) {

            frm.add_custom_button('Refresh Status', function() {

                frappe.call({
                    method: "your_app.api.payment.refresh_payment_status",
                    args: {
                        payment_id: frm.doc.payment_id
                    },
                    freeze: true,
                    freeze_message: "Checking Razorpay payment status..."
                }).then(r => {

                    if (r.message) {
                        frm.reload_doc();
                        frappe.msgprint("Payment status updated");
                    }

                });

            }, "Actions");
        }

        // -------- VIEW IN RAZORPAY BUTTON --------
        if (frm.doc.payment_id) {

            frm.add_custom_button('View in Razorpay', function() {

                window.open(
                    "https://dashboard.razorpay.com/app/payments/" + frm.doc.payment_id
                );

            }, "Actions");
        }

    }
});
